import type { MetadataRoute } from "next";

/**
 * PWA manifest - generated at build time by Next.js.
 *
 * Makes ForexMind installable on mobile home screens ("Add to Home
 * Screen" in iOS Safari / "Install app" in Chrome Android). Once
 * installed, the app opens in a standalone window (no browser chrome)
 * with its own icon on the home screen.
 *
 * Served at /manifest.webmanifest (Next.js convention for manifest.ts).
 *
 * Icons: the 192x192 and 512x512 PNGs are generated by src/app/icon.tsx
 * via ImageResponse at build time - no binary files in the repo.
 *
 * Notes on choices:
 *  - display: "standalone" - looks like a native app when installed.
 *  - orientation: "portrait" - the app is responsive but is primarily
 *    used portrait on mobile; landscape still works.
 *  - theme_color: dark theme background (#0a0a0a) so the Android
 *    status bar / iOS title bar match the app's dark UI.
 *  - start_url: "/" - opens on the dashboard.
 *  - No service worker yet: caching strategy needs careful design to
 *    avoid serving stale journal data. The manifest alone enables
 *    installability; offline support is a future phase.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "ForexMind - AI Forex Risk Assistant",
    short_name: "ForexMind",
    description:
      "AI-assisted forex education, risk management, journaling and trade-checking. Advisory only - never financial advice.",
    start_url: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#0a0a0a",
    theme_color: "#0a0a0a",
    categories: ["finance", "productivity", "education"],
    icons: [
      {
        src: "/icon",
        sizes: "192x192",
        type: "image/png",
      },
      {
        src: "/apple-icon",
        sizes: "180x180",
        type: "image/png",
      },
    ],
  };
}
